function validate([root]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs at least one node.';
  // Slot i of the level-order list belongs to the real node number floor((i - 1) / 2).
  const depth = [1];
  for (let i = 1; i < root.length; i++) {
    const parent = Math.floor((i - 1) / 2);
    if (parent >= depth.length) return 'Every value after the root needs a parent node.';
    if (root[i] !== null) depth.push(depth[parent] + 1);
  }
  if (root.some(v => v !== null && (!Number.isInteger(v) || v < -99 || v > 99))) return 'Node values are whole numbers from -99 to 99.';
  if (depth.length > 1024) return 'The tree has at most 2^10 nodes.';
  if (Math.max(...depth) > 10) return 'The tree is at most 10 levels deep.';
  return null;
}

