function printTree(root) {
  function height(node) {
    if (node === null) {
      return -1;
    }
    return 1 + Math.max(height(node.left), height(node.right));
  }
  const treeHeight = height(root);
  const rows = treeHeight + 1;
  const cols = 2 ** rows - 1;
  const res = Array.from({ length: rows }, () => new Array(cols).fill(''));
  function place(node, row, col) {
    if (node === null) {
      return;
    }
    res[row][col] = String(node.val);
    const offset = 2 ** (treeHeight - row - 1);
    place(node.left, row + 1, col - offset);
    place(node.right, row + 1, col + offset);
  }
  place(root, 0, (cols - 1) / 2);
  return res;
}

