function printTree(root) {
  // Breadth first: count the levels, then give each node the centre of the column range it owns.
  let levels = 0;
  for (let level = [root]; level.length; levels++) level = level.flatMap(node => [node.left, node.right].filter(Boolean));
  const width = Math.pow(2, levels) - 1;
  const grid = [];
  for (let r = 0; r < levels; r++) grid.push(Array(width).fill(''));
  const queue = [[root, 0, 0, width - 1]];
  while (queue.length) {
    const [node, r, lo, hi] = queue.shift();
    const mid = (lo + hi) >> 1;
    grid[r][mid] = '' + node.val;
    if (node.left) queue.push([node.left, r + 1, lo, mid - 1]);
    if (node.right) queue.push([node.right, r + 1, mid + 1, hi]);
  }
  return grid;
}

