function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const value = () => large || rand() < 0.5 ? pick(199) - 99 : pick(7) - 3;
  if (large && rand() < 0.3) {
    // A perfect tree of depth 10 has no gaps, so its list is just the 1023 values.
    return [Array.from({ length: 1023 }, value)];
  }
  const count = large ? 300 + pick(400) : 1 + pick(10);
  const deep = rand() < 0.4;
  const nodes = [{ val: value(), left: null, right: null, depth: 1 }];
  for (let tries = 0; nodes.length < count && tries < 100000; tries++) {
    const parent = deep ? nodes[Math.max(0, nodes.length - 1 - pick(2))] : nodes[pick(nodes.length)];
    const side = rand() < 0.5 ? 'left' : 'right';
    if (parent[side] || parent.depth >= 10) continue;
    const node = { val: value(), left: null, right: null, depth: parent.depth + 1 };
    parent[side] = node;
    nodes.push(node);
  }
  const out = [];
  const queue = [nodes[0]];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    out.push(node ? node.val : null);
    if (node) queue.push(node.left, node.right);
  }
  while (out[out.length - 1] === null) out.pop();
  return [out];
}
